/**
 * Server-only: the docs library (src/data/docs-library.json, generated by scripts/generate-content.py)
 * merged with pages edited, added or hidden in RanEddie Studio.
 */
import library from '@/data/docs-library.json';
import { slugify, type DocPage, type SiteContent } from './content';

const LIBRARY = library as DocPage[];
const LIBRARY_BY_SLUG = new Map(LIBRARY.map((d) => [d.slug, d]));

/** Every published docs page, in reading order. */
export function allDocs(content: Pick<SiteContent, 'docs' | 'docsRemoved'>): DocPage[] {
  const removed = new Set(content.docsRemoved ?? []);
  const overrides = new Map((content.docs ?? []).map((d) => [d.slug, d]));
  const out = LIBRARY.filter((d) => !removed.has(d.slug)).map((d) => overrides.get(d.slug) ?? d);
  // Pages added in Studio go after the last page of their section (or at the end).
  for (const d of content.docs ?? []) {
    if (LIBRARY_BY_SLUG.has(d.slug)) continue;
    let at = -1;
    out.forEach((x, i) => {
      if (x.section === d.section) at = i;
    });
    if (at < 0) out.push(d);
    else out.splice(at + 1, 0, d);
  }
  return out;
}

/** Turns the full list edited in Studio back into what's stored: only changes and removals. */
export function toStoredDocs(full: DocPage[]): { docs: DocPage[]; docsRemoved: string[] } {
  const present = new Set(full.map((d) => d.slug));
  const docs = full.filter((d) => {
    const base = LIBRARY_BY_SLUG.get(d.slug);
    return !base || base.title !== d.title || base.section !== d.section || base.description !== d.description || base.body !== d.body;
  });
  const docsRemoved = LIBRARY.filter((d) => !present.has(d.slug)).map((d) => d.slug);
  return { docs, docsRemoved };
}

export type DocLink = { slug: string; section: string; title: string; description: string };
export const toLink = ({ slug, section, title, description }: DocPage): DocLink => ({ slug, section, title, description });

export function sections(docs: DocPage[]) {
  const map = new Map<string, DocPage[]>();
  for (const d of docs) map.set(d.section, [...(map.get(d.section) ?? []), d]);
  return [...map.entries()].map(([name, items]) => ({ name, slug: slugify(name), items }));
}

/** Simple ranked search over titles, descriptions and text. */
export function searchDocs(docs: DocPage[], query: string, limit = 10): DocLink[] {
  const terms = query.toLowerCase().split(/\s+/).filter(Boolean).slice(0, 8);
  if (!terms.length) return [];
  const scored: [number, DocPage][] = [];
  for (const d of docs) {
    const title = d.title.toLowerCase();
    const desc = `${d.description} ${d.section}`.toLowerCase();
    const body = d.body.toLowerCase();
    let score = 0;
    for (const t of terms) {
      if (title.includes(t)) score += title.startsWith(t) ? 12 : 8;
      else if (desc.includes(t)) score += 4;
      else if (body.includes(t)) score += 1;
      else {
        score = 0;
        break;
      }
    }
    if (score) scored.push([score, d]);
  }
  return scored
    .sort((a, b) => b[0] - a[0])
    .slice(0, limit)
    .map(([, d]) => toLink(d));
}
